def _pause(job):
    """LATE_FEES_PAUSE in the environment wins over the file.

    Both are read as booleans (1/yes/true/on, 0/no/false/off). An empty
    variable counts as unset. Any other value raises ValueError, so the job
    fails instead of guessing whether to charge.
    """
    raw = os.environ.get("LATE_FEES_PAUSE", "").strip()
    if not raw:
        return job.getboolean("pause", fallback=False)
    value = configparser.ConfigParser.BOOLEAN_STATES.get(raw.lower())
    if value is None:
        raise ValueError(f"LATE_FEES_PAUSE={raw!r} is not a boolean (use 1/0, yes/no)")
    return value


